<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import api, { errorMessage, validationErrors } from '../../composables/useAdminApi'
import AdminPageHeader from '../../components/AdminPageHeader.vue'
import AdminStatusBadge from '../../components/AdminStatusBadge.vue'
import AdminConfirmDialog from '../../components/AdminConfirmDialog.vue'

const props=defineProps({id:String}); const router=useRouter(); const client=ref(null); const loading=ref(true); const error=ref(''); const tab=ref('overview'); const editingContact=ref(null); const contactErrors=ref({}); const showArchive=ref(false); const busy=ref(false)
const blank=()=>({first_name:'',last_name:'',email:'',phone:'',position:'',active:true,can_access_portal:false,can_accept_documents:false}); const contactForm=reactive(blank())
async function load(){try{client.value=(await api.get(`/clients/${props.id}`)).data.data}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
onMounted(load)
function editContact(contact=null){editingContact.value=contact?.id??'new';Object.assign(contactForm,contact??blank())}
function closeContact(){editingContact.value=null;contactErrors.value={};Object.assign(contactForm,blank())}
function portalChanged(){if(!contactForm.can_access_portal)contactForm.can_accept_documents=false}
function signerChanged(){if(contactForm.can_accept_documents)contactForm.can_access_portal=true}
async function saveContact(){busy.value=true;contactErrors.value={};try{if(editingContact.value==='new')await api.post(`/clients/${props.id}/contacts`,contactForm);else await api.put(`/clients/${props.id}/contacts/${editingContact.value}`,contactForm);closeContact();await load()}catch(e){contactErrors.value=validationErrors(e);error.value=errorMessage(e)}finally{busy.value=false}}
async function archive(){busy.value=true;try{await api.post(`/clients/${props.id}/archive`);router.push({name:'clients.index'})}finally{busy.value=false}}
const title=computed(()=>client.value?.display_label??'Client')
</script>

<template><div class="space-y-6"><AdminPageHeader :title="title" eyebrow="Client detail"><template v-if="client"><button class="admin-button admin-button--quiet" @click="showArchive=true">Archive</button><RouterLink class="admin-button bg-dark text-light" :to="{name:'clients.edit',params:{id}}">Edit client</RouterLink></template></AdminPageHeader><p v-if="error" class="border border-red-700 bg-red-50 p-4 text-sm text-red-800">{{error}}</p><p v-if="loading" class="py-20 text-center">Loading…</p><template v-else-if="client"><nav class="flex gap-6 border-b border-dark font-mono text-xs font-bold uppercase"><button v-for="item in ['overview','contacts','projects']" :key="item" class="border-b-4 px-1 pb-3 capitalize" :class="tab===item?'border-accent':'border-transparent'" @click="tab=item">{{item}}</button></nav><section v-if="tab==='overview'" class="grid gap-5 lg:grid-cols-2"><div class="border border-dark bg-light p-6"><div class="flex items-center justify-between"><h2 class="font-mono font-bold uppercase">Legal information</h2><AdminStatusBadge :status="client.status" /></div><dl class="mt-6 grid grid-cols-[120px_1fr] gap-y-3 text-sm"><dt class="text-neutral-500">Legal name</dt><dd>{{client.name}}</dd><dt class="text-neutral-500">Trading name</dt><dd>{{client.display_name||'—'}}</dd><dt class="text-neutral-500">IČO</dt><dd>{{client.registration_number||'—'}}</dd><dt class="text-neutral-500">DIČ</dt><dd>{{client.tax_number||'—'}}</dd><dt class="text-neutral-500">IČ DPH</dt><dd>{{client.vat_number||'—'}}</dd></dl></div><div class="border border-dark bg-light p-6"><h2 class="font-mono font-bold uppercase">Addresses & notes</h2><h3 class="mt-6 text-xs font-bold uppercase">Registered</h3><p class="mt-2 whitespace-pre-line text-sm">{{client.registered_address||'—'}}</p><h3 class="mt-5 text-xs font-bold uppercase">Billing</h3><p class="mt-2 whitespace-pre-line text-sm">{{client.billing_address||client.billing_details||'—'}}</p><h3 class="mt-5 text-xs font-bold uppercase">Internal notes</h3><p class="mt-2 whitespace-pre-line text-sm text-neutral-600">{{client.internal_notes||'—'}}</p></div></section><section v-if="tab==='contacts'" class="space-y-4"><div class="flex justify-end"><button class="admin-button bg-dark text-light" @click="editContact()">Add contact</button></div><div class="border border-dark bg-light"><article v-for="contact in client.contacts" :key="contact.id" class="grid gap-4 border-b border-neutral-300 p-4 last:border-0 sm:grid-cols-[1fr_auto]"><div><strong>{{contact.name}}</strong><p class="mt-1 text-sm text-neutral-600">{{contact.position||'Contact'}} · {{contact.email}}</p><div class="mt-3 flex flex-wrap gap-2"><AdminStatusBadge :status="contact.active"/><span class="border border-neutral-400 px-2 py-1 font-mono text-[10px] font-bold uppercase">Portal: {{contact.can_access_portal?'yes':'no'}}</span><span class="border border-neutral-400 px-2 py-1 font-mono text-[10px] font-bold uppercase">Signer: {{contact.can_accept_documents?'yes':'no'}}</span></div></div><button class="admin-button admin-button--quiet" @click="editContact(contact)">Edit</button></article><p v-if="!client.contacts.length" class="p-10 text-center text-sm text-neutral-600">No contacts yet.</p></div></section><section v-if="tab==='projects'" class="border border-dark bg-light"><RouterLink v-for="project in client.projects" :key="project.id" :to="{name:'projects.show',params:{id:project.id}}" class="grid grid-cols-[1fr_auto] gap-4 border-b border-neutral-300 p-4 last:border-0"><div><strong>{{project.name}}</strong><p class="mt-1 text-xs text-neutral-600">{{project.service_product?.name||'No service product'}}</p></div><AdminStatusBadge :status="project.status"/></RouterLink><p v-if="!client.projects.length" class="p-10 text-center text-sm text-neutral-600">No projects yet.</p></section></template><div v-if="editingContact" class="fixed inset-0 z-40 overflow-y-auto bg-dark/55 p-4"><form class="mx-auto my-8 max-w-xl space-y-4 border border-dark bg-light p-6" @submit.prevent="saveContact"><div class="flex justify-between"><h2 class="font-mono text-xl font-bold">{{editingContact==='new'?'New contact':'Edit contact'}}</h2><button type="button" aria-label="Close" @click="closeContact">✕</button></div><div class="grid gap-4 sm:grid-cols-2"><div class="admin-field"><label>First name</label><input v-model="contactForm.first_name" required><p v-if="contactErrors.first_name" class="admin-error">{{contactErrors.first_name[0]}}</p></div><div class="admin-field"><label>Last name</label><input v-model="contactForm.last_name" required></div></div><div class="admin-field"><label>Email</label><input v-model="contactForm.email" type="email" required></div><div class="grid gap-4 sm:grid-cols-2"><div class="admin-field"><label>Phone</label><input v-model="contactForm.phone"></div><div class="admin-field"><label>Position</label><input v-model="contactForm.position"></div></div><div class="space-y-3 border-t border-neutral-300 pt-4"><label class="flex gap-3"><input v-model="contactForm.active" type="checkbox"> Active contact</label><label class="flex gap-3"><input v-model="contactForm.can_access_portal" type="checkbox" @change="portalChanged"> Can access portal</label><label class="flex gap-3"><input v-model="contactForm.can_accept_documents" type="checkbox" @change="signerChanged"> Can accept documents</label><p v-if="contactErrors.can_accept_documents" class="admin-error">{{contactErrors.can_accept_documents[0]}}</p></div><div class="flex justify-end gap-2"><button type="button" class="admin-button admin-button--quiet" @click="closeContact">Cancel</button><button class="admin-button bg-dark text-light" :disabled="busy">{{busy?'Saving…':'Save contact'}}</button></div></form></div><AdminConfirmDialog :open="showArchive" title="Archive client?" text="The client remains available historically but will no longer appear as active." confirm-label="Archive client" :busy="busy" @close="showArchive=false" @confirm="archive" /></div></template>